module borg_sentry (\n    input clk, rst_n, start,\n    input [3:0] N, L,\n    input [3:0] walk0, walk1, walk2, walk3, walk4, walk5, walk6, walk7,\n    input [3:0] degree0, degree1, degree2, degree3, degree4, degree5, degree6, degree7,\n    input [3:0] neighbors0_0, neighbors0_1, neighbors0_2, neighbors0_3, neighbors0_4, neighbors0_5, neighbors0_6, neighbors0_7,\n    input [3:0] neighbors1_0, neighbors1_1, neighbors1_2, neighbors1_3, neighbors1_4, neighbors1_5, neighbors1_6, neighbors1_7,\n    input [3:0] neighbors2_0, neighbors2_1, neighbors2_2, neighbors2_3, neighbors2_4, neighbors2_5, neighbors2_6, neighbors2_7,\n    input [3:0] neighbors3_0, neighbors3_1, neighbors3_2, neighbors3_3, neighbors3_4, neighbors3_5, neighbors3_6, neighbors3_7,\n    input [3:0] neighbors4_0, neighbors4_1, neighbors4_2, neighbors4_3, neighbors4_4, neighbors4_5, neighbors4_6, neighbors4_7,\n    input [3:0] neighbors5_0, neighbors5_1, neighbors5_2, neighbors5_3, neighbors5_4, neighbors5_5, neighbors5_6, neighbors5_7,\n    input [3:0] neighbors6_0, neighbors6_1, neighbors6_2, neighbors6_3, neighbors6_4, neighbors6_5, neighbors6_6, neighbors6_7,\n    input [3:0] neighbors7_0, neighbors7_1, neighbors7_2, neighbors7_3, neighbors7_4, neighbors7_5, neighbors7_6, neighbors7_7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // FSM States\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_LOAD = 4'd1;\n    localparam [3:0] S_INIT = 4'd2;\n    localparam [3:0] S_STEP_RESET = 4'd3;\n    localparam [3:0] S_STEP_LOOP = 4'd4;\n    localparam [3:0] S_FINAL_SUM = 4'd5;\n    localparam [3:0] S_DONE = 4'd6;\n\n    // Local Parameters\n    localparam FIXED_SHIFT = 24;\n    localparam [31:0] ONE = 32'd1 << FIXED_SHIFT;\n\n    // Internal Registers\n    reg [3:0] state, next_state;\n    reg [3:0] t_step;\n    reg [3:0] current_node;\n    reg [3:0] neighbor_idx;\n\n    // Walk and Graph Storage\n    reg [3:0] walk_reg [0:7];\n    reg [3:0] degree_reg [0:7];\n    reg [3:0] neighbors_reg [0:7][0:7];\n\n    // Probability Tables\n    reg [31:0] prob_current [0:7];\n    reg [31:0] prob_next [0:7];\n\n    // Temporary Calculation Signals\n    reg [31:0] step_prob;\n    reg node_error_flag;\n    reg [7:0] cycle_counter;\n\n    // Initialize all registered arrays\n    integer init_i, init_j;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (init_i = 0; init_i < 8; init_i = init_i + 1) begin\n                walk_reg[init_i] <= 4'd0;\n                degree_reg[init_i] <= 4'd0;\n                prob_current[init_i] <= 32'd0;\n                prob_next[init_i] <= 32'd0;\n                for (init_j = 0; init_j < 8; init_j = init_j + 1) begin\n                    neighbors_reg[init_i][init_j] <= 4'd0;\n                end\n            end\n        end\n    end\n\n    // FSM Control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            t_step <= 4'd0;\n            current_node <= 4'd0;\n            neighbor_idx <= 4'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n            cycle_counter <= 8'd0;\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= S_LOAD;\n                        current_node <= 4'd0;\n                    end\n                end\n\n                S_LOAD: begin\n                    case (current_node)\n                        4'd0: begin\n                            walk_reg[0] <= walk0;\n                            walk_reg[1] <= walk1;\n                            walk_reg[2] <= walk2;\n                            walk_reg[3] <= walk3;\n                            walk_reg[4] <= walk4;\n                            walk_reg[5] <= walk5;\n                            walk_reg[6] <= walk6;\n                            walk_reg[7] <= walk7;\n\n                            neighbors_reg[0][0] <= neighbors0_0;\n                            neighbors_reg[0][1] <= neighbors0_1;\n                            neighbors_reg[0][2] <= neighbors0_2;\n                            neighbors_reg[0][3] <= neighbors0_3;\n                            neighbors_reg[0][4] <= neighbors0_4;\n                            neighbors_reg[0][5] <= neighbors0_5;\n                            neighbors_reg[0][6] <= neighbors0_6;\n                            neighbors_reg[0][7] <= neighbors0_7;\n\n                            degree_reg[0] <= degree0;\n                            current_node <= 4'd1;\n                        end\n                        // Similar blocks for current_node = 1-7 loading neighbors1-7 and degrees1-7\n                        default: current_node <= current_node + 4'd1;\n                    endcase\n\n                    if (current_node == 4'd7) begin\n                        state <= S_INIT;\n                        current_node <= 4'd0;\n                    end\n                end\n\n                S_INIT: begin\n                    if (current_node < N) begin\n                        if (current_node == walk_reg[0]) begin\n                            prob_current[current_node] <= 32'd0;\n                        end else begin\n                            prob_current[current_node] <= ONE / N;\n                        end\n                        current_node <= current_node + 4'd1;\n                    end else begin\n                        state <= S_STEP_RESET;\n                        current_node <= 4'd0;\n                        t_step <= 4'd1;\n                    end\n                end\n\n                S_STEP_RESET: begin\n                    if (current_node < N) begin\n                        prob_next[current_node] <= 32'd0;\n                        current_node <= current_node + 4'd1;\n                    end else begin\n                        state <= S_STEP_LOOP;\n                        current_node <= 4'd0;\n                        neighbor_idx <= 4'd0;\n                    end\n                end\n\n                S_STEP_LOOP: begin\n                    if (t_step < L) begin\n                        if (current_node < N) begin\n                            if (neighbor_idx < degree_reg[current_node]) begin\n                                step_prob <= prob_current[current_node] / degree_reg[current_node];\n                                // Transition logic implementation here\n                                neighbor_idx <= neighbor_idx + 4'd1;\n                            end else begin\n                                current_node <= current_node + 4'd1;\n                                neighbor_idx <= 4'd0;\n                            end\n                        end else begin\n                            // Swap probability tables\n                            for (init_i = 0; init_i < 8; init_i = init_i + 1) begin\n                                prob_current[init_i] <= prob_next[init_i];\n                                prob_next[init_i] <= 32'd0;\n                            end\n                            t_step <= t_step + 4'd1;\n                            state <= (t_step + 1 < L) ? S_STEP_RESET : S_FINAL_SUM;\n                            current_node <= 4'd0;\n                        end\n                    end\n                end\n\n                S_FINAL_SUM: begin\n                    if (current_node < N) begin\n                        result <= result + prob_current[current_node];\n                        current_node <= current_node + 4'd1;\n                    end else begin\n                        state <= S_DONE;\n                    end\n                end\n\n                S_DONE: begin\n                    done <= 1'b1;\n                    if (!start) state <= S_IDLE;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n\n            // Safety timeout\n            if (cycle_counter > 8'd200) begin\n                state <= S_DONE;\n            end\n        end\n    end\n\nendmodule